//! CABIN · SIM
//!   · yard: the track graph the extractor writes and the game reads
//!   · consts: every tunable number, tagged solid or assumed
//!   · signal: signals generated by rule, written into the yard by cabin-osm
//!   · route: every route a signal can set, built at load
//!   · NDLS: the New Delhi yard, baked into the build
//!
//! `World`, the seeded `Rng` and the interlocking arrive in B4.

pub mod consts;
pub mod route;
pub mod signal;
pub mod yard;

/// The yard the game ships with, written by `cabin-osm`. Baked in, so the
/// page never fetches: the game plays the extract of `Yard::osm_base`.
pub const NDLS: &str = include_str!("../../../data/ndls.yard");

#[cfg(test)]
mod tests {
    #[test]
    fn the_baked_yard_parses() {
        let y = crate::yard::Yard::parse(crate::NDLS).expect("data/ndls.yard parses");
        assert_eq!(y.platforms.len(), 16);
    }
}
